mapper.insert:
insert into batch.external_event_delivery (
    tenant_id, event_source, event_id, event_code, biz_date, request_id,
    payload_snapshot, target_workflow_definition_ids, trace_id
) values (
    #{tenantId}, #{eventSource}, #{eventId}, #{eventCode}, #{bizDate}, #{requestId},
    cast(#{payloadSnapshot} as jsonb), cast(#{targetWorkflowDefinitionIds} as jsonb), #{traceId}
)
on conflict (tenant_id, event_source, event_id) do nothing

mapper.select:
select *
from batch.external_event_delivery
where tenant_id = #{tenantId}
  and event_source = #{eventSource}
  and event_id = #{eventId}
for update

select delivery_id
from batch.external_event_delivery_alias
where tenant_id = #{tenantId}
  and idempotency_key = #{idempotencyKey}

select exists (
    select 1
    from batch.external_event_delivery
    where tenant_id = #{tenantId}
      and event_source = #{eventSource}
      and event_id = #{eventId}
      and jsonb_exists(target_workflow_definition_ids, cast(#{workflowDefinitionId} as varchar))
)

select *
from batch.external_event_delivery
where tenant_id = #{tenantId}
  and event_source = #{eventSource}
  and event_id = #{eventId}

select delivery.*
from batch.external_event_delivery_alias alias
join batch.external_event_delivery delivery
  on delivery.tenant_id = alias.tenant_id
 and delivery.id = alias.delivery_id
where alias.tenant_id = #{tenantId}
  and alias.idempotency_key = #{idempotencyKey}
  and delivery.event_source = #{eventSource}
